import{_ as s,C as o,o as n,c,a3 as i,E as p,w as m,j as e,a}from"./chunks/framework.D-espDCU.js";const d="/versions/cli/v1.3.45/screens/perform/macro_rows_device.png",l="/versions/cli/v1.3.45/screens/perform/rack_ctrl_dense.png",A=JSON.parse('{"title":"Device parameter macro rows","description":"","frontmatter":{},"headers":[],"relativePath":"perform/macro-rows/device-parameter.md","filePath":"perform/macro-rows/device-parameter.md"}'),h={name:"perform/macro-rows/device-parameter.md"};function g(v,r,u,_,f,w){const t=o("ManualRelated");return n(),c("div",null,[r[1]||(r[1]=i('<h1 id="device-parameter-macro-rows" tabindex="-1">Device parameter macro rows <a class="header-anchor" href="#device-parameter-macro-rows" aria-label="Permalink to &quot;Device parameter macro rows&quot;">​</a></h1><p>A <strong>DEVICE</strong> macro turns the knob into a control for a device in one of your <a href="./../../racks/">racks</a>: the arpeggiator&#39;s gate, Seed&#39;s density, a Scaler&#39;s scale. It sends no MIDI itself; the device plays the result.</p><p><img src="'+d+'" alt="Four device macros in rack 01 GENERATIVE" class="screen"></p><p>The row reads rack, device, parameter, then the value in the device&#39;s own units: <strong>01 GENERATIVE ARP GATE 72%</strong>. A rack with no name shows as <strong>RACK 1</strong>–<strong>RACK 8</strong>.</p><p>The knob changes the device&#39;s own setting, the same as editing it on the device&#39;s page. On that page, the parameter shows a badge with the knob number. Delete the device and the row reads <strong>SET TARGET</strong>.</p><h2 id="rack-bypass" tabindex="-1">Rack BYPASS <a class="header-anchor" href="#rack-bypass" aria-label="Permalink to &quot;Rack BYPASS&quot;">​</a></h2><p>A rack&#39;s <strong>BYPASS</strong> is a whole-rack switch, not a device parameter: its row reads the rack name and <strong>BYPASS</strong>, with <strong>ON</strong> or <strong>OFF</strong> on the right and a two-sided switch bar. The knob bypasses the rack from the middle up. A <strong>RACK CTRL</strong> macro with no rack set reads <strong>SET TARGET</strong>.</p><p><img src="'+l+'" alt="RACK CTRL on the second row of four macros" class="screen"></p><p>Set it up from the rack menu, or pick <strong>RACK CTRL</strong> in the macro&#39;s <strong>MODE</strong>: <a href="./../../macros/rack-control">RACK CTRL</a>.</p><p>Set these macros up: <a href="./../../macros/device-parameter">DEVICE macro</a>.</p>',10)),p(t,null,{default:m(()=>[...r[0]||(r[0]=[e("ul",null,[e("li",null,[e("a",{href:"./"},"Macro rows")]),e("li",null,[e("a",{href:"./../../devices/"},"Devices"),a(" — Every device and its parameters")]),e("li",null,[e("a",{href:"./../../concepts/mapping"},"Mapping"),a(" — Knobs, macros and parameters")])],-1)])]),_:1})])}const T=s(h,[["render",g]]);export{A as __pageData,T as default};
